def gen(rng):
    def fmt(ws):
        return str(len(ws)) + '\n' + ' '.join(ws)
    al = 'abcdefghijklmnopqrstuvwxyz'
    def word(k, a=al):
        return ''.join(rng.choice(a) for _ in range(k))
    t = [fmt(['a']), fmt(['abc']), fmt(['racecar']), fmt(['a', 'b', 'c']), fmt(['ab', 'ba']), fmt(['zzzz', 'yx'])]
    for _ in range(30):
        w = rng.randint(1, 8)
        t.append(fmt([word(rng.randint(1, 8), rng.choice([al, 'ab', 'abc'])) for _ in range(w)]))
    t.append(fmt([word(10) for _ in range(100000)]))
    t.append(fmt([word(1000000)]))
    t.append(fmt([word(rng.randint(1, 18)) for _ in range(100000)]))
    t.append(fmt(['a'] * 100000))
    return t
